 static object Get(object x,string n)=>x.GetType().GetField(n,Any) is FieldInfo f?f.GetValue(x):x.GetType().GetProperty(n,Any).GetValue(x);
 static void Set(object x,string n,object v)=>x.GetType().GetField(n,Any).SetValue(x,v);
 static object Call(object x,string n,params object[] a)=>x.GetType().GetMethods(Any).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length&&m.GetParameters().Select((p,i)=>a[i]==null||(p.ParameterType.IsByRef?p.ParameterType.GetElementType():p.ParameterType).IsInstanceOfType(a[i])).All(v=>v)).Invoke(x,a);
 static bool Surface(object earth,Vector3 p,out RaycastHit hit){object[] args={p,default(RaycastHit)};bool found=(bool)earth.GetType().GetMethod("Surface").Invoke(earth,args);hit=(RaycastHit)args[1];return found;}
 static bool ClearRay(object earth,Vector3 p,float bottom)=>Surface(earth,p,out RaycastHit hit)?hit.point.y<bottom+.12f:(bool)Call(earth,"HasActualGroundHole",p);
