 static void NoActualTerrainPenetration(object earth,BoxCollider shape)
 {
  Bounds b=shape.bounds;foreach(var other in Physics.OverlapBox(b.center,b.extents+Vector3.one*.08f,Quaternion.identity,~0,QueryTriggerInteraction.Ignore))if((bool)Call(earth,"IsTerrain",other)){bool overlap=Physics.ComputePenetration(shape,shape.transform.position,shape.transform.rotation,other,other.transform.position,other.transform.rotation,out _,out float depth);Assert.That(!overlap||depth<=.015f,Is.True,"Original actual terrain penetration veto remains strict: "+depth);}
 }
