   int editsBefore=(int)Get(earth,"ActualEdits"),passesBefore=(int)Get(earth,"ExposurePasses");float clockBefore=(float)Get(match,"Clock"),initialY=body.position.y,maxY=initialY;bool dynamic=false,checkedClear=false,withdrawalPaused=false;float originalFixedStep=Time.fixedDeltaTime;match.enabled=true;Time.timeScale=8;float end=Time.realtimeSinceStartup+(observeFirstRelease?75:90),next=0;
